  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (i, reason) => { throw new ScanError(lines[i], cols[i], reason) }
  const tokens = []
  let i = 0

  // Digit run where '_' is allowed between two digits of the same run.
  const run = (j, ok) => {
    if (!ok(cs[j])) return j
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      let depth = 1
      let j = i + 2
      while (j < n && depth > 0) {
        if (cs[j] === '/' && cs[j + 1] === '*') { depth++; j += 2 }
        else if (cs[j] === '*' && cs[j + 1] === '/') { depth--; j += 2 }
        else j++
