      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      push('rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
