        if (j === i + 2) bad = true
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          let k = j + 1
          if (cs[k] === '+' || cs[k] === '-') k++
          if (isDigit(cs[k])) j = run(k, isDigit)
