export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (cs[i] === '\n') { l++; c = 1 }
    else if (cs[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (i, reason) => { throw new ScanError(lines[i], cols[i], reason) }
  const tokens = []
  let i = 0

  // Digit run where '_' is allowed between two digits of the same run.
  const run = (j, ok) => {
    if (!ok(cs[j])) return j
    while (j < n) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      let depth = 1
      let j = i + 2
      while (j < n && depth > 0) {
        if (cs[j] === '/' && cs[j + 1] === '*') { depth++; j += 2 }
        else if (cs[j] === '*' && cs[j + 1] === '/') { depth--; j += 2 }
        else j++
      }
      if (depth > 0) fail(i, 'unterminated block comment')
      i = j
      continue
    }
    const start = i
    const push = (kind, body) => tokens.push({ line: lines[start], col: cols[start], kind, body })
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      push('rawstring', JSON.stringify(cs.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
      const p = (cs[i + 1] || '').toLowerCase()
      if (ch === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const ok = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        j = run(i + 2, ok)
        if (j === i + 2) bad = true
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          let k = j + 1
          if (cs[k] === '+' || cs[k] === '-') k++
          if (isDigit(cs[k])) j = run(k, isDigit)
        }
      }
      if (bad || isIdPart(cs[j])) {
        while (j < n && isIdPart(cs[j])) j++
        fail(start, 'invalid number ' + cs.slice(i, j).join(''))
      }
      push('number', cs.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let out = ''
      for (;;) {
        if (j >= n) fail(start, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { out += d; j++; continue }
        if (j + 1 >= n) fail(start, 'unterminated string')
        const e = cs[j + 1]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { out += simple[e]; j += 2 }
        else if (e === 'x') {
          if (!isHex(cs[j + 2]) || !isHex(cs[j + 3])) fail(j, 'invalid escape \\x')
          out += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16))
          j += 4
        } else if (e === 'u') {
          if (cs[j + 2] !== '{') fail(j, 'invalid escape \\u')
          let k = j + 3
          let h = ''
          while (isHex(cs[k])) h += cs[k++]
          if (h === '' || cs[k] !== '}' || parseInt(h, 16) > 0x10ffff) fail(j, 'invalid escape \\u')
          out += String.fromCodePoint(parseInt(h, 16))
          j = k + 1
        } else fail(j, 'invalid escape \\' + e)
      }
      push('string', JSON.stringify(out))
      i = j
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { push('punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push('punct', ch); i++; continue }
    fail(i, 'unexpected character ' + ch)
  }
  return tokens
}
